import{z as d,x as A,o as t,c as B,q as l,j as s,D as r,d as o,s as E,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"IRDS 路线图","description":"","frontmatter":{"title":"IRDS 路线图","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/irds-roadmap.md","filePath":"litho/irds-roadmap.md","lastUpdated":1791413859000}'),D={name:"litho/irds-roadmap.md"};function p(h,a,S,m,C,R){const i=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="irds-路线图" tabindex="-1">IRDS 路线图 <a class="header-anchor" href="#irds-路线图" aria-label="Permalink to &quot;IRDS 路线图&quot;">​</a></h1><div class="epigraph"><p>ITRS 停更之后，IRDS 用器件与系统视角列光刻需求：它是共识表，不是某厂承诺，更不是物理定律。</p><footer>—— 对照 IEEE IRDS（International Roadmap for Devices and Systems）及其 Lithography 章节的定位</footer></div><p><a href="/litho/transistor-density-metric">上一课</a>统一了密度口径。缺口是行业共识表从哪来。本课钉 IRDS。表上的层成本如何落到晶圆，留给<a href="/litho/cost-per-layer-wafer">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IRDS 继承 ITRS 的「需求表」角色：未来节点的节距、套刻、CDU、EUV/DUV 选项、计量。用途：设备与材料供应商对齐研发，不是代工厂的 PDK。读表时要看年份与「要求 vs 已知解」。把 IRDS 行当成 ASML 出货计划，会错。</p><p><span class="marginnote">IRDS 的前身是 ITRS（国际半导体技术路线图）。2016 年改组时名字里「Technology」换成了「Devices and Systems」：不再预言「工艺会缩到几纳米」，而是从器件与系统的需要出发，倒推光刻、计量各要交什么——从趋势预言书变成了需求清单。</span></p><p>缺口是<strong>共识需求 vs 交付</strong>，不是再争节点名。表中的 overlay/CD 预算结构可与掩模 CDU 课对照，数值仍随版次变，课文不抄死表。</p><h3 id="与-dtco-的关系" tabindex="-1">与 DTCO 的关系 <a class="header-anchor" href="#与-dtco-的关系" aria-label="Permalink to &quot;与 DTCO 的关系&quot;">​</a></h3><p>IRDS 给行业边界；DTCO 在某厂机台集合内选点。厂可以比表激进或保守。光刻课程用 IRDS 当对照骨架，用厂公开路径当实例，二者标注来源。</p><p><span class="marginnote">IRDS 含 More than Moore、封装、光子。后课替代形态会回到这些章，本课先钉：它不是只服务逻辑 CMOS 平面缩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读 Lithography 章：关键层半节距、多重 vs EUV、计量缺口。对照自己的 CPP/MMP。缺口表（没有已知解的红格）才是研究课题，不是已量产。</p>',12)),(t(),s(n,null,{default:r(()=>[E(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20T%5B%22IRDS%20Lithography%20%E7%AB%A0%22%5D%20--%3E%20Y%5B%22%E6%A0%87%E6%B3%A8%E7%89%88%E6%AC%A1%E4%B8%8E%E5%B9%B4%E4%BB%BD%22%5D%0A%20%20Y%20--%3E%20ROW%5B%22%E5%85%B3%E9%94%AE%E5%B1%82%E5%8D%8A%E8%8A%82%E8%B7%9D%20%2F%20%E5%A5%97%E5%88%BB%20%2F%20CDU%22%5D%0A%20%20ROW%20--%3E%20COLOR%7B%22%E6%9C%89%E5%B7%B2%E7%9F%A5%E8%A7%A3%3F%22%7D%0A%20%20COLOR%20--%3E%7C%22%E7%BB%BF%E6%A0%BC%22%7C%20SOL%5B%22%E9%87%8F%E4%BA%A7%E8%B7%AF%E5%BE%84%20%E5%BD%93%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20COLOR%20--%3E%7C%22%E7%BA%A2%E6%A0%BC%22%7C%20GAP%5B%22%E7%A0%94%E7%A9%B6%E7%BC%BA%E5%8F%A3%20%E4%B8%8D%E6%98%AF%E4%BA%A7%E8%83%BD%22%5D%0A%20%20SOL%20--%3E%20CPP%5B%22%E5%AF%B9%E7%85%A7%E8%87%AA%E5%B7%B1%20CPP%20%2F%20MMP%22%5D%0A%20%20GAP%20--%3E%20CPP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"这张图回答的问题是：拿到一张 IRDS 表之后的操作顺序——先钉年份，再分绿格红格，最后落到自己的节距指标上对照。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"「红格」直觉类比：像点名时没人举手的题目——需求摆在那里，全行业还没有已知解。这正是研究与研发部门该去填的坑；绿格则已有量产方案。引用路线图时把红格说成现有产能，是新手最常见的翻车点。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"路线图是委员会博弈后的需求投影，受物理（随机、DOF）与工业（单一来源）约束。它滞后或超前于某厂都正常。物理极限课将与表中 Hyper-NA 之后的红格对照。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"常见误区：把路线图当时刻表。「表上写 2028 年某指标」不是谁承诺 2028 年出货，而是委员会认为 2028 年前后行业需要这个能力。厂商实际交付可以早两年，也可能永远不来——尤其涉及单一供应商的行。")],-1)),(t(),s(n,null,{default:r(()=>[E(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRDS%5B%22IRDS%20%E9%9C%80%E6%B1%82%E8%A1%A8%22%5D%20--%3E%20IND%5B%22%E8%AE%BE%E5%A4%87%E6%9D%90%E6%96%99%E5%AF%B9%E9%BD%90%22%5D%0A%20%20FAB%5B%22%E4%BB%A3%E5%B7%A5%20DTCO%22%5D%20--%3E%20PDK%5B%22%E5%8F%AF%E4%BA%A4%E4%BB%98%20PDK%22%5D%0A%20%20IRDS%20-.-%3E%7C%22%E5%AF%B9%E7%85%A7%22%7C%20FAB%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某年版数值当 2026 永远有效。不发明 IRDS 未写的 arXiv。IRDS 不报价。</p><p>后课默认：行业需求有公开表；下一课把需求翻译成每层与每晶圆成本结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IRDS 是共识需求路线，不是厂承诺或物理定律。</li><li>读「要求 vs 已知解」；红格才是研究。</li><li>与 DTCO 对照使用，不互相替代。</li><li>出处：IEEE IRDS Lithography 章节定位。</li></ul>',5))])}const P=d(D,[["render",p]]);export{u as __pageData,P as default};
